import java.util.*;

class Solution {
  public int[][] matrixRankTransform(int[][] matrix) {
    int rows = matrix.length;
    int columns = matrix[0].length;
    List<int[]> cells = new ArrayList<>();
    for (int r = 0; r < rows; r++)
      for (int c = 0; c < columns; c++) cells.add(new int[] {matrix[r][c], r, c});
    cells.sort(Comparator.comparingInt(a -> a[0]));
    int[] rowRank = new int[rows];
    int[] columnRank = new int[columns];
    int[][] answer = new int[rows][columns];
    int index = 0;
    while (index < cells.size()) {
      int end = index;
      while (end < cells.size() && cells.get(end)[0] == cells.get(index)[0]) end++;
      int groupSize = end - index;
      int[] parent = new int[groupSize];
      for (int i = 0; i < groupSize; i++) parent[i] = i;
      Map<Integer, Integer> rowOwner = new HashMap<>();
      Map<Integer, Integer> columnOwner = new HashMap<>();
      for (int i = 0; i < groupSize; i++) {
        int[] cell = cells.get(index + i);
        union(parent, i, rowOwner.putIfAbsent(cell[1], i) == null ? i : rowOwner.get(cell[1]));
        union(
            parent, i, columnOwner.putIfAbsent(cell[2], i) == null ? i : columnOwner.get(cell[2]));
      }
      Map<Integer, Integer> componentRank = new HashMap<>();
      for (int i = 0; i < groupSize; i++) {
        int[] cell = cells.get(index + i);
        int root = find(parent, i);
        int rank = Math.max(rowRank[cell[1]], columnRank[cell[2]]) + 1;
        componentRank.put(root, Math.max(componentRank.getOrDefault(root, 0), rank));
      }
      for (int i = 0; i < groupSize; i++) {
        int[] cell = cells.get(index + i);
        int rank = componentRank.get(find(parent, i));
        answer[cell[1]][cell[2]] = rank;
        rowRank[cell[1]] = Math.max(rowRank[cell[1]], rank);
        columnRank[cell[2]] = Math.max(columnRank[cell[2]], rank);
      }
      index = end;
    }
    return answer;
  }

  private int find(int[] parent, int node) {
    if (parent[node] != node) parent[node] = find(parent, parent[node]);
    return parent[node];
  }

  private void union(int[] parent, int first, int second) {
    first = find(parent, first);
    second = find(parent, second);
    if (first != second) parent[first] = second;
  }
}
